WITH gaps AS (SELECT *, CASE WHEN txn_time - LAG(txn_time) OVER (PARTITION BY merchant ORDER BY txn_time, id) > INTERVAL 14 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM transactions), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY merchant ORDER BY txn_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_id FROM gaps) SELECT DATE_TRUNC('MONTH', txn_time) AS activity_month, CASE WHEN is_new_burst >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS is_new_burst_tier, COUNT_IF(merchant = 'Starbucks') AS starbucks_events, MIN(txn_time) AS first_txn_time, STDDEV_SAMP(amount) AS amount_stddev, MAX(txn_time) AS ended_at, COUNT(*) FILTER (WHERE merchant = 'Amazon') AS amazon_rows, SUM(CASE WHEN txn_type = 'REFUND' THEN is_new_burst ELSE 0 END) AS refund_is_new_burst, GROUPING(DATE_TRUNC('MONTH', txn_time)) AS grouping_id FROM sessionized GROUP BY CUBE (DATE_TRUNC('MONTH', txn_time), CASE WHEN is_new_burst >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY amazon_rows;
